KeyPair.prototype._importPrivate = function _importPrivate(key, enc) {
  // 安全修复：确保输入被正确初始化
  let cleanKey;

  if (key == null) {
    throw new Error('Private key cannot be null or undefined');
  }

  // 处理不同类型的输入
  if (Buffer.isBuffer(key)) {
    // 复制缓冲区，避免操作原始内存
    cleanKey = Buffer.alloc(key.length);
    key.copy(cleanKey);
  } else if (typeof key === 'string') {
    // 字符串直接传递给 BN（BN 会正确处理）
    cleanKey = key;
  } else if (Array.isArray(key) || (key instanceof Uint8Array)) {
    // 数组或类数组转为 Buffer，确保数据被复制
    cleanKey = Buffer.from(key);
  } else {
    // 其他类型（包括 BN 对象）直接使用
    cleanKey = key;
  }

  // 创建 BN 实例
  this.priv = new BN(cleanKey, enc || 16);

  // 验证私钥不为零且在有效范围内
  if (this.priv.isZero()) {
    throw new Error('Invalid private key: must not be zero');
  }

  // Ensure that the priv won't be bigger than n, otherwise we may fail
  // in fixed multiplication method
  this.priv = this.priv.umod(this.ec.curve.n);

  // 额外验证：检查私钥是否有效（不为0且小于n）
  if (this.priv.isZero() || this.priv.cmp(this.ec.curve.n) >= 0) {
    throw new Error('Invalid private key');
  }
};

KeyPair.prototype._importPublic = function _importPublic(key, enc) {
  if (key.x || key.y) {
    // Montgomery points only have an `x` coordinate.
    // Weierstrass/Edwards points on the other hand have both `x` and
    // `y` coordinates.
    if (this.ec.curve.type === 'mont') {
      assert(key.x, 'Need x coordinate');
    } else if (this.ec.curve.type === 'short' ||
               this.ec.curve.type === 'edwards') {
      assert(key.x && key.y, 'Need both x and y coordinate');
    }
    this.pub = this.ec.curve.point(key.x, key.y);
    return;
  }
  this.pub = this.ec.curve.decodePoint(key, enc);
};

// ECDH
KeyPair.prototype.derive = function derive(pub) {
  if(!pub.validate()) {
    assert(pub.validate(), 'public point not validated');
  }
  return pub.mul(this.priv).getX();
};

// ECDSA
KeyPair.prototype.sign = function sign(msg, enc, options) {
  return this.ec.sign(msg, this, enc, options);
};

KeyPair.prototype.verify = function verify(msg, signature, options) {
  return this.ec.verify(msg, signature, this, undefined, options);
};

KeyPair.prototype.inspect = function inspect() {
  return '<Key priv: ' + (this.priv && this.priv.toString(16, 2)) +
         ' pub: ' + (this.pub && this.pub.inspect()) + ' >';
};
